/* Fundo calmo: foto com deriva lenta, brilho suave e partículas leves. Pequenas variações a cada dia. */
(function(){
const IMG="data:image/jpeg;base64,";
const cv=document.createElement('canvas');cv.id='bgfx';cv.setAttribute('aria-hidden','true');document.body.prepend(cv);
const x=cv.getContext('2d');if(!x)return;
const dn=Math.floor((Date.now()-new Date().getTimezoneOffset()*6e4)/864e5);
let a=(dn*40503+7)>>>0;const rnd=()=>{a=(a*1664525+1013904223)>>>0;return a/4294967296};
const dir=rnd()<.5?-1:1,ph=rnd()*20,ax=.42+rnd()*.16,N=30+Math.floor(rnd()*20);
const P=[...Array(N)].map(()=>({x:rnd(),y:rnd(),r:.6+rnd()*1.7,s:4+rnd()*10,o:rnd()*6.28,a:.12+rnd()*.3}));
let W,H;function fit(){const q=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;cv.width=W*q;cv.height=H*q;x.setTransform(q,0,0,q,0,0)}
fit();addEventListener('resize',fit);
const img=new Image();
img.onload=()=>{
 const iw=img.naturalWidth,ih=img.naturalHeight;
 const sm=document.createElement('canvas');sm.width=48;sm.height=32;sm.getContext('2d').drawImage(img,0,0,48,32);
 function frame(ms){
  const t=ms/1000,lk=document.body.classList.contains('locked');
  x.clearRect(0,0,W,H);x.imageSmoothingEnabled=true;x.imageSmoothingQuality='high';
  const sc=Math.max(W/iw,H/ih)*(1.08+.04*Math.sin(t*.05+ph)),w=iw*sc,h=ih*sc;
  const px=W*ax-w*ax+dir*Math.sin(t*.04+ph)*W*.015,py=(H-h)/2+Math.cos(t*.033+ph)*H*.012;
  x.globalCompositeOperation='lighter';x.globalAlpha=.15;x.drawImage(sm,px-w*.05,py-h*.05,w*1.1,h*1.1);
  x.globalAlpha=.3+.025*Math.sin(t*.2+ph);x.drawImage(img,px,py,w,h);
  const cx=(((t*.012+ph*.07)%1.6)-.3)*W,sw=x.createLinearGradient(cx-W*.2,0,cx+W*.2,H*.6);sw.addColorStop(0,'rgba(255,255,255,0)');sw.addColorStop(.5,'rgba(255,255,255,.025)');sw.addColorStop(1,'rgba(255,255,255,0)');x.globalAlpha=1;x.fillStyle=sw;x.fillRect(0,0,W,H);
  P.forEach(p=>{const Y=(((p.y*H-t*p.s)%H)+H)%H,X=p.x*W+Math.sin(t*.3+p.o)*18,al=p.a*.6*(.6+.4*Math.sin(t*.8+p.o));x.fillStyle=`rgba(255,255,255,${al})`;x.beginPath();x.arc(X,Y,p.r,0,6.283);x.fill()});
  x.globalCompositeOperation='source-over';
  x.fillStyle='rgba(5,6,10,.5)';x.fillRect(0,0,W,H);
  if(lk){x.fillStyle='rgba(255,48,48,.1)';x.fillRect(0,0,W,H)}
  const M=Math.max(W,H),vg=x.createRadialGradient(W/2,H/2,M*.25,W/2,H/2,M*.8);vg.addColorStop(0,'rgba(0,0,0,0)');vg.addColorStop(1,'rgba(0,0,0,.6)');x.fillStyle=vg;x.fillRect(0,0,W,H)}
 if(matchMedia('(prefers-reduced-motion:reduce)').matches)frame(0);
 else{const lp=ms=>{frame(ms);requestAnimationFrame(lp)};requestAnimationFrame(lp)}
};
img.src=IMG;
})();
